package com.ahols.gmpowertrain;
import android.app.*;import android.os.*;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 BluetoothSocket socket; InputStream in; OutputStream out; LinearLayout root; TextView status,output; EditText command; final String SPP="00001101-0000-1000-8000-00805F9B34FB"; StringBuilder logs=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b); if(Build.VERSION.SDK_INT>=31&&checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT","android.permission.BLUETOOTH_SCAN"},100); ui();}
 void ui(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,16,16,16);root.setBackgroundColor(0xff101820);sc.addView(root);setContentView(sc);TextView h=new TextView(this);h.setText("GM POWERTRAIN DIAGNOSTICS\nELM327 • OBD-II");h.setTextSize(22);h.setTextColor(0xff80cbc4);root.addView(h);status=new TextView(this);status.setText("Disconnected");status.setTextColor(-1);root.addView(status);
 button("Connect paired ELM327",this::pick);button("Initialize adapter",()->cmds(new String[]{"ATZ","ATE0","ATL0","ATS0","ATH0","ATSP0"}));button("Vehicle information (Mode 09)",()->cmds(new String[]{"0902","0904","090A"}));button("Stored DTCs (03)",()->cmds(new String[]{"03"}));button("Pending DTCs (07)",()->cmds(new String[]{"07"}));button("Permanent DTCs (0A)",()->cmds(new String[]{"0A"}));button("Readiness (0101)",()->cmds(new String[]{"0101"}));button("Freeze frame",()->cmds(new String[]{"0200","020C","0205","020D"}));button("Live sensor snapshot",()->cmds(new String[]{"010C","0105","010D","0111","0104","010F","010B","010E"}));button("Clear codes (04)",()->new AlertDialog.Builder(this).setMessage("Clearing codes erases evidence and may reset emissions readiness. Continue?").setNegativeButton("Cancel",null).setPositiveButton("Clear",(d,w)->cmds(new String[]{"04"})).show());
 TextView t=new TextView(this);t.setText("COMMAND TERMINAL");t.setTextColor(0xff80cbc4);root.addView(t);command=new EditText(this);command.setHint("ELM/OBD command, e.g. 010C");root.addView(command);button("Send command",()->{String s=command.getText().toString().trim();if(!s.isEmpty())cmds(new String[]{s});});button("Export/share session log",this::export);output=new TextView(this);output.setTextColor(-1);root.addView(output);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
 void pick(){try{BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter();if(a==null){status.setText("Bluetooth unavailable");return;}Set<BluetoothDevice> ds=a.getBondedDevices();ArrayList<BluetoothDevice> list=new ArrayList<>(ds);String[] names=new String[list.size()];for(int n=0;n<list.size();n++)names[n]=list.get(n).getName()+" "+list.get(n).getAddress();if(list.isEmpty()){status.setText("Pair adapter in Android settings first");return;}new AlertDialog.Builder(this).setTitle("Choose paired device").setItems(names,(d,w)->connect(list.get(w))).show();}catch(Exception e){status.setText(e.toString());}}
 void connect(BluetoothDevice d){status.setText("Connecting…");new Thread(()->{try{BluetoothSocket s=d.createRfcommSocketToServiceRecord(UUID.fromString(SPP));s.connect();socket=s;in=s.getInputStream();out=s.getOutputStream();runOnUiThread(()->status.setText("Connected: "+d.getName()));}catch(Exception e){runOnUiThread(()->status.setText("Connect failed: "+e.getMessage()));}}).start();}
 void cmds(String[] cs){new Thread(()->{for(String c:cs)try{String r=send(c);String line="> "+c+"\n"+r+"\n";logs.append(line);runOnUiThread(()->output.append(line));}catch(Exception e){runOnUiThread(()->status.setText("Error: "+e.getMessage()));break;}}).start();}
 String send(String c)throws Exception{if(out==null)throw new IOException("Not connected");out.write((c+"\r").getBytes("US-ASCII"));out.flush();ByteArrayOutputStream b=new ByteArrayOutputStream();long until=System.currentTimeMillis()+3500;while(System.currentTimeMillis()<until){if(in.available()>0){int x=in.read();if(x=='>')break;b.write(x);}else Thread.sleep(40);}return b.toString("US-ASCII").replace("\r","\n").trim();}
 void export(){try{File f=new File(getExternalFilesDir(null),"diagnostic-log.txt");try(FileWriter w=new FileWriter(f)){w.write(logs.toString());}Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,logs.toString());startActivity(Intent.createChooser(i,"Share log"));}catch(Exception e){status.setText(e.toString());}}
 public void onDestroy(){super.onDestroy();try{if(socket!=null)socket.close();}catch(Exception e){}}
}